suppressWarnings(suppressMessages(library(GenomicRanges)))
z <- function(l, v) cat(l, ":", paste(ifelse(is.na(v),"NA",v-1L), collapse=","), "\n")
al <- function(l,h) cat(l, ":", paste(sprintf("%d-%d", queryHits(h)-1L, subjectHits(h)-1L), collapse=" "), "\n")
Q <- GRanges("c:8-10:*")
S <- GRanges("c", IRanges(c(19,1),c(24,0)), strand=c("-","*"))
al("follow", follow(Q,S,select="all")); al("precede", precede(Q,S,select="all"))
S2 <- GRanges("c", IRanges(c(19,1),c(24,2)), strand=c("-","*")); al("follow2 (non-zero *)", follow(Q,S2,select="all")); al("precede2", precede(Q,S2,select="all"))
S3 <- GRanges("c", IRanges(c(19,1),c(24,3)), strand=c("-","*")); al("follow3 (end 3)", follow(Q,S3,select="all"));
S4 <- GRanges("c", IRanges(c(19,5),c(24,6)), strand=c("-","*")); al("follow4 ([5,6]* dist1)", follow(Q,S4,select="all"));
S5 <- GRanges("c", IRanges(c(12,5),c(13,6)), strand=c("-","*")); al("follow5 [12,13]- dist1 vs [5,6]* dist1", follow(Q,S5,select="all")); al("precede5", precede(Q,S5,select="all"))
S6 <- GRanges("c", IRanges(c(14,5),c(15,6)), strand=c("-","*")); al("follow6 [14,15]- dist3 vs [5,6]* dist1", follow(Q,S6,select="all"))
S7 <- GRanges("c", IRanges(c(14,1),c(15,3)), strand=c("-","*")); al("follow7 [14,15]- dist3 vs [1,3]* dist4", follow(Q,S7,select="all"))
S8 <- GRanges("c", IRanges(c(30,1),c(32,3)), strand=c("-","*")); al("follow8 [30,32]- dist19 vs [1,3]* dist4", follow(Q,S8,select="all"))
S9 <- GRanges("c", IRanges(c(30,1),c(32,3)), strand=c("-","+")); al("follow9 + instead", follow(Q,S9,select="all"))
S10 <- GRanges("c", IRanges(c(14,1),c(15,3)), strand=c("-","+")); al("follow10 - near, + far", follow(Q,S10,select="all")); al("precede10", precede(Q,S10,select="all"))
S11 <- GRanges("c", IRanges(c(14,5),c(15,6)), strand=c("+","-")); al("follow11 + right, - left", follow(Q,S11,select="all")); al("precede11", precede(Q,S11,select="all"))
cat("punion strands\n")
gs <- function(x) as.character(strand(x))
for (a in c("+","-","*")) for (b in c("+","-","*")) cat("punion", a, b, ":", tryCatch(gs(punion(GRanges("a",IRanges(1,3),strand=a), GRanges("a",IRanges(2,5),strand=b))), error=function(e) "ERR"), " pint:", tryCatch(gs(pintersect(GRanges("a",IRanges(1,3),strand=a), GRanges("a",IRanges(2,5),strand=b))), error=function(e) "ERR"), " psd:", tryCatch(gs(psetdiff(GRanges("a",IRanges(1,3),strand=a), GRanges("a",IRanges(2,5),strand=b))), error=function(e) "ERR"),"\n")
